fn dividir(a: f64, b: f64) -> Result<f64, String> {
    if b == 0.0 {
        Err(String::from("Divisão por zero"))
    } else {
        Ok(a / b)
    }
}

fn mostrar() {
    match dividir(10.0, 2.0) {
        Ok(res) => println!("Resultado: {}", res),
        Err(e) => println!("Erro: {}", e),
    }
}

